# Hypothesis: fill a "hole": bg cells enclosed by pattern lines -> color 1. Verify demo3.
def enclose(g,bg):
    h=len(g); w=len(g[0])
    out=[row[:] for row in g]
    # flood fill from border over bg; unreached bg cells = holes
    seen=[[False]*w for _ in range(h)]
    st=[]
    for i in range(h):
        for j in [0,w-1]:
            if g[i][j]==bg and not seen[i][j]: st.append((i,j)); seen[i][j]=True
    for j in range(w):
        for i in [0,h-1]:
            if g[i][j]==bg and not seen[i][j]: st.append((i,j)); seen[i][j]=True
    while st:
        i,j=st.pop()
        for di,dj in ((1,0),(-1,0),(0,1),(0,-1)):
            ni,nj=i+di,j+dj
            if 0<=ni<h and 0<=nj<w and g[ni][nj]==bg and not seen[ni][nj]:
                seen[ni][nj]=True; st.append((ni,nj))
    for i in range(h):
        for j in range(w):
            if g[i][j]==bg and not seen[i][j]: out[i][j]=1
    return out
