# For each demo: try both orientations of (tgt,ref); compute candidate fills for every shift s; compare with expected changed cells.
def analyze(n,orient='sparseTgt'):
    gi=G[f'Demo pair {n} input']; go=G[f'Demo pair {n} output']
    segs,bgv=segments(gi)
    def pat(s): return sum(1 for rr in s for c in range(len(gi[0])) if gi[rr][c]!=bgv)
    o=(segs[0],segs[1]) if orient=='sparseTgt' else (segs[1],segs[0])
    T,R=o
