    expchg=[(r,c) for r in range(len(go)) for c in range(W) if gi[r][c]==bgv and go[r][c]!=bgv]
    exprel={((r-T[0])%H,c) for r,c in expchg}  # rel coords
    oksets=[]
    for tgtR,refR in [(0,1),(1,0)]:
        A,B=sub2(segs[tgtR],gi),sub2(segs[refR],gi)
        ms={s:(sum(1 for kk in range(H) for c in range(W) if A[kk][c]!=B[kk][(c+s)%W]),
               sum(1 for kk in range(H) for c in range(W) if A[kk][c]==bgv and B[kk][(c+s)%W]!=bgv)) for s in range(W)}
        cand=[s for sv in ms.values() if sv[0]==min(v[0] for v in ms.values())]
        for s in cand+[None]:
            fill={(kk,c) for kk in range(H) for c in range(W) if A[kk][c]==bgv and B[kk][(c+s)%W]!=bgv} if s is not None else {}
            if fill==exprel:
                oksets.append((tgtR,refR,s,'exact'))
    return sorted(oksets),len(expchg),ms if False else None
def sub2(rows,g): return [g[r] for r in rows]
for n in [1,2,3,4,5,6,7,8]:
    o,nc,_=analyze(n)
